package com.pp.shaderlod.lod.terrain.mixin;import net.minecraft.client.Options;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.*;import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
@Mixin(Options.class)public abstract class EffectiveRenderDistanceMixin{@Inject(method="getEffectiveRenderDistance()I",at=@At("RETURN"),cancellable=true,require=1)private void radius(CallbackInfoReturnable<Integer> callback){callback.setReturnValue(com.pp.shaderlod.lod.terrain.GeometryLodController.effectiveChunks(callback.getReturnValue()));}}
